module laser_tag #(\n    parameter WIDTH = 32,\n    parameter FRAC_BITS = 16\n) (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [WIDTH-1:0] x1, y1, x2, y2, x3, y3,\n    output reg [WIDTH-1:0] low_y,\n    output reg [WIDTH-1:0] high_y,\n    output reg low_inf,\n    output reg high_inf,\n    output reg can_hit,\n    output reg done\n);\n    \n    // State definitions\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] COMPUTE_A_B = 4'd1;\n    localparam [3:0] COMPUTE_C = 4'd2;\n    localparam [3:0] COMPUTE_D = 4'd3;\n    localparam [3:0] COMPUTE_DENOM = 4'd4;\n    localparam [3:0] COMPUTE_S_PRIME = 4'd5;\n    localparam [3:0] CHECK_CAN_HIT = 4'd6;\n    localparam [3:0] COMPUTE_ENDPOINT1 = 4'd7;\n    localparam [3:0] COMPUTE_ENDPOINT2 = 4'd8;\n    localparam [3:0] DETERMINE_RESULT = 4'd9;\n    localparam [3:0] DONE_STATE = 4'd10;\n    \n    reg [3:0] state, next_state;\n    reg [WIDTH-1:0] A, B, C, D, denom;\n    reg [WIDTH-1:0] Sx, Sy;\n    reg [WIDTH-1:0] x_min, x_max;\n    reg [WIDTH-1:0] dx, dy, t;\n    reg [WIDTH-1:0] y_values_0, y_values_1;\n    reg inf_flags_0, inf_flags_1;\n    reg signed_flag_0, signed_flag_1;\n    reg [1:0] endpoint_count;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd200;\n    \n    // Fixed-point multiplication helper\n    function [WIDTH-1:0] mult;\n        input [WIDTH-1:0] a, b;\n        begin\n            mult = (a * b) >>> FRAC_BITS;\n        end\n    endfunction\n    \n    // Fixed-point division helper (simplified)\n    function [WIDTH-1:0] divide;\n        input [WIDTH-1:0] num, denom;\n        begin\n            divide = num / denom;\n        end\n    endfunction\n    \n    // State transition logic\n    always @(*) begin\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = COMPUTE_A_B;\n                end else begin\n                    next_state = IDLE;\n                end\n            end\n            COMPUTE_A_B: next_state = COMPUTE_C;\n            COMPUTE_C: next_state = COMPUTE_D;\n            COMPUTE_D: next_state = COMPUTE_DENOM;\n            COMPUTE_DENOM: next_state = COMPUTE_S_PRIME;\n            COMPUTE_S_PRIME: next_state = CHECK_CAN_HIT;\n            CHECK_CAN_HIT: begin\n                if ((Sx > 0 && x_min >= Sx) || (Sx < 0 && x_max <= Sx) || (Sx == 0)) begin\n                    next_state = DONE_STATE;\n                end else begin\n                    next_state = COMPUTE_ENDPOINT1;\n                end\n            end\n            COMPUTE_ENDPOINT1: begin\n                if (endpoint_count == 0) begin\n                    next_state = COMPUTE_ENDPOINT2;\n                end else begin\n                    next_state = DETERMINE_RESULT;\n                end\n            end\n            COMPUTE_ENDPOINT2: next_state = DETERMINE_RESULT;\n            DETERMINE_RESULT: next_state = DONE_STATE;\n            DONE_STATE: begin\n                if (!start) begin\n                    next_state = IDLE;\n                end else begin\n                    next_state = DONE_STATE;\n                end\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // State register with reset\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            low_inf <= 1'b0;\n            high_inf <= 1'b0;\n            can_hit <= 1'b0;\n            A <= {WIDTH{1'b0}};\n            B <= {WIDTH{1'b0}};\n            C <= {WIDTH{1'b0}};\n            D <= {WIDTH{1'b0}};\n            denom <= {WIDTH{1'b0}};\n            Sx <= {WIDTH{1'b0}};\n            Sy <= {WIDTH{1'b0}};\n            x_min <= {WIDTH{1'b0}};\n            x_max <= {WIDTH{1'b0}};\n            dx <= {WIDTH{1'b0}};\n            dy <= {WIDTH{1'b0}};\n            t <= {WIDTH{1'b0}};\n            y_values_0 <= {WIDTH{1'b0}};\n            y_values_1 <= {WIDTH{1'b0}};\n            inf_flags_0 <= 1'b0;\n            inf_flags_1 <= 1'b0;\n            signed_flag_0 <= 1'b0;\n            signed_flag_1 <= 1'b0;\n            endpoint_count <= 2'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            state <= next_state;\n            cycle_count <= cycle_count + 8'd1;\n        end\n    end\n    \n    // Main computation logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Already handled in state register\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        x_min <= (x1 < x2) ? x1 : x2;\n                        x_max <= (x1 > x2) ? x1 : x2;\n                        endpoint_count <= 2'd0;\n                    end\n                end\n                COMPUTE_A_B: begin\n                    A <= y2 - y1;\n                    B <= x1 - x2;\n                end\n                COMPUTE_C: begin\n                    C <= -(mult(A, x1) + mult(B, y1));\n                end\n                COMPUTE_D: begin\n                    D <= mult(A, x3) + mult(B, y3) + C;\n                end\n                COMPUTE_DENOM: begin\n                    denom <= mult(A, A) + mult(B, B);\n                end\n                COMPUTE_S_PRIME: begin\n                    if (denom != 0) begin\n                        Sx <= x3 - (2 * mult(A, D)) / denom;\n                        Sy <= y3 - (2 * mult(B, D)) / denom;\n                    end else begin\n                        Sx <= {WIDTH{1'b0}};\n                        Sy <= {WIDTH{1'b0}};\n                    end\n                end\n                CHECK_CAN_HIT: begin\n                    if ((Sx > 0 && x_min >= Sx) || (Sx < 0 && x_max <= Sx) || (Sx == 0)) begin\n                        can_hit <= 1'b0;\n                    end else begin\n                        can_hit <= 1'b1;\n                    end\n                end\n                COMPUTE_ENDPOINT1: begin\n                    if (endpoint_count == 0) begin\n                        dx <= x1 - Sx;\n                        dy <= y1 - Sy;\n                    end else begin\n                        dx <= x2 - Sx;\n                        dy <= y2 - Sy;\n                    end\n                    if (dx == 0) begin\n                        if (endpoint_count == 0) begin\n                            inf_flags_0 <= 1'b1;\n                            signed_flag_0 <= (dy > 0) ? 1'b1 : 1'b0;\n                        end else begin\n                            inf_flags_1 <= 1'b1;\n                            signed_flag_1 <= (dy > 0) ? 1'b1 : 1'b0;\n                        end\n                    end else begin\n                        t <= (-Sx) / dx;\n                        if (endpoint_count == 0) begin\n                            inf_flags_0 <= 1'b0;\n                            y_values_0 <= Sy + mult(t, dy);\n                        end else begin\n                            inf_flags_1 <= 1'b0;\n                            y_values_1 <= Sy + mult(t, dy);\n                        end\n                    end\n                    endpoint_count <= endpoint_count + 2'd1;\n                end\n                COMPUTE_ENDPOINT2: begin\n                    dx <= x2 - Sx;\n                    dy <= y2 - Sy;\n                    if (dx == 0) begin\n                        inf_flags_1 <= 1'b1;\n                        signed_flag_1 <= (dy > 0) ? 1'b1 : 1'b0;\n                    end else begin\n                        t <= (-Sx) / dx;\n                        inf_flags_1 <= 1'b0;\n                        y_values_1 <= Sy + mult(t, dy);\n                    end\n                    endpoint_count <= endpoint_count + 2'd1;\n                end\n                DETERMINE_RESULT: begin\n                    if (inf_flags_0 && inf_flags_1) begin\n                        low_inf <= signed_flag_0 ? 1'b0 : 1'b1;\n                        high_inf <= signed_flag_1 ? 1'b1 : 1'b0;\n                        low_y <= {WIDTH{1'b0}};\n                        high_y <= {WIDTH{1'b0}};\n                    end else if (inf_flags_0) begin\n                        low_inf <= 1'b1;\n                        high_inf <= 1'b0;\n                        low_y <= {WIDTH{1'b0}};\n                        high_y <= y_values_1;\n                    end else if (inf_flags_1) begin\n                        low_inf <= 1'b0;\n                        high_inf <= 1'b1;\n                        low_y <= y_values_0;\n                        high_y <= {WIDTH{1'b0}};\n                    end else begin\n                        low_inf <= 1'b0;\n                        high_inf <= 1'b0;\n                        low_y <= (y_values_0 < y_values_1) ? y_values_0 : y_values_1;\n                        high_y <= (y_values_0 > y_values_1) ? y_values_0 : y_values_1;\n                    end\n                end\n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n                default: begin\n                    state <= IDLE;\n                    done <= 1'b0;\n                end\n            endcase\n        end\n    end\n    \n    // Safety: Prevent infinite loops\n    always @(posedge clk) begin\n        if (cycle_count >= MAX_CYCLES) begin\n            state <= IDLE;\n            done <= 1'b1;\n            cycle_count <= 8'd0;\n        end\n    end\n    \nendmodule